76	// Insertion-ordered mapping with Python dict semantics: setting an existing
77	// key replaces the value but keeps the original key object and position.
78	export class YamlMap {
79	  constructor() {
80	    this._slots = new Map(); // normKey -> [origKey, value]
81	    this._order = [];        // normKeys in first-insertion order
82	  }
83	  set(key, value) {
84	    const norm = normalizeKey(key);
85	    if (this._slots.has(norm)) {
86	      this._slots.get(norm)[1] = value;
87	    } else {
88	      this._slots.set(norm, [key, value]);
89	      this._order.push(norm);
90	    }
91	  }
92	  get(key) {
93	    const slot = this._slots.get(normalizeKey(key));
94	    return slot ? slot[1] : undefined;
95	  }
96	  has(key) {
97	    return this._slots.has(normalizeKey(key));
98	  }
99	  get size() {
100	    return this._order.length;
101	  }
102	  // Array of [origKey, value] pairs in insertion order.
103	  entries() {
104	    return this._order.map((k) => this._slots.get(k));
