// argparse.mjs — minimal reimplementation of Python's argparse behavior for
// the exact parser:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//
// Only node builtins are used. No RegExp, no JSON.

import process from 'node:process';

// Long option strings in add_argument order (the -h/--help action is added
// first by ArgumentParser itself).
const LONG_OPTIONS = ['--help', '--a'];

function buildUsage(prog) {
  return `usage: ${prog} [-h] --a A\n`;
}

function buildHelp(prog) {
  return (
    buildUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function errorExit(prog, message) {
  process.stderr.write(buildUsage(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit(prog) {
  process.stdout.write(buildHelp(prog));
  process.exit(0);
}

function isAsciiDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isAllDigits(s) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    if (!isAsciiDigit(s[i])) return false;
  }
  return true;
}

// Mirrors argparse's _negative_number_matcher: ^-\d+$ | ^-\d*\.\d+$
// (\d restricted to ASCII digits; see note in module docs/deviations).
function isNegativeNumber(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  if (isAllDigits(rest)) return true; // -\d+
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  if (fracPart.indexOf('.') !== -1) return false; // at most one dot
  if (fracPart.length === 0) return false; // need \d+ after the dot
  if (!isAllDigits(fracPart)) return false;
  if (intPart.length > 0 && !isAllDigits(intPart)) return false;
  return true;
}

// Minimal Python repr() for strings, used in the
// "ignored explicit argument %r" error message.
function pyRepr(s) {
  let quote = "'";
  if (s.indexOf("'") !== -1 && s.indexOf('"') === -1) {
    quote = '"';
  }
  let out = quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = ch.charCodeAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 32 || code === 127) {
      const hex = code.toString(16);
      out += '\\x' + (hex.length < 2 ? '0' + hex : hex);
    } else out += ch;
  }
  out += quote;
  return out;
}

// Classify one token the way argparse's _parse_optional does.
// Returns one of:
//   { kind: 'value' }                                  — consumed as a value / positional
//   { kind: 'unknown' }                                — looks like an option but matches nothing
//   { kind: 'option', name, explicit, fromEq }         — a known option
// name is '-h', '--help' or '--a'; explicit is the inline argument (or null);
// fromEq records whether explicit came from an '=' split (matters for -h).
function classifyToken(tok, prog) {
  if (tok === '') return { kind: 'value' };
  if (tok[0] !== '-') return { kind: 'value' };

  // exact option strings
  if (tok === '-h' || tok === '--help' || tok === '--a') {
    return { kind: 'option', name: tok, explicit: null, fromEq: false };
  }

  // a single '-' is a value
  if (tok.length === 1) return { kind: 'value' };

  // "opt=explicit" where opt is an exact option string
  const eq = tok.indexOf('=');
  if (eq !== -1) {
    const head = tok.slice(0, eq);
    if (head === '-h' || head === '--help' || head === '--a') {
      return { kind: 'option', name: head, explicit: tok.slice(eq + 1), fromEq: true };
    }
  }

  if (tok[1] === '-') {
    // long option: unambiguous prefix (abbreviation) matching
    const prefix = eq === -1 ? tok : tok.slice(0, eq);
    const explicit = eq === -1 ? null : tok.slice(eq + 1);
    const matches = [];
    for (let i = 0; i < LONG_OPTIONS.length; i++) {
      if (LONG_OPTIONS[i].startsWith(prefix)) matches.push(LONG_OPTIONS[i]);
    }
    if (matches.length > 1) {
      errorExit(prog, `ambiguous option: ${tok} could match ${matches.join(', ')}`);
    }
    if (matches.length === 1) {
      return { kind: 'option', name: matches[0], explicit, fromEq: eq !== -1 };
    }
  } else {
    // single-dash: concatenated short options, e.g. -hx -> -h with tail 'x'
    if (tok.slice(0, 2) === '-h') {
      return { kind: 'option', name: '-h', explicit: tok.slice(2), fromEq: false };
    }
  }

  // negative numbers are values (this parser has no number-like options)
  if (isNegativeNumber(tok)) return { kind: 'value' };

  // contains a space -> meant to be a positional
  if (tok.indexOf(' ') !== -1) return { kind: 'value' };

  return { kind: 'unknown' };
}

export function parseArgs(argv, prog) {
  // Pass 1: classify every token (argparse builds the option/argument pattern
  // for the whole command line before consuming anything, so errors raised
  // here — e.g. ambiguous options — take precedence over everything else,
  // including -h/--help appearing earlier).
  const classified = new Array(argv.length);
  let afterSeparator = false;
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (afterSeparator) {
      classified[i] = { kind: 'value' };
    } else if (tok === '--') {
      afterSeparator = true;
      classified[i] = { kind: 'sep' };
    } else {
      classified[i] = classifyToken(tok, prog);
    }
  }

  // Pass 2: consume left to right.
  let a = undefined;
  let aSeen = false;
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const tok = argv[i];
    const c = classified[i];

    if (c.kind === 'sep') {
      // This argparse version keeps the '--' itself in the extras.
      extras.push('--');
      i++;
      continue;
    }
    if (c.kind === 'value' || c.kind === 'unknown') {
      extras.push(tok);
      i++;
      continue;
    }

    // c.kind === 'option'
    if (c.name === '-h' || c.name === '--help') {
      if (c.fromEq) {
        errorExit(prog, `argument -h/--help: ignored explicit argument ${pyRepr(c.explicit)}`);
      }
      printHelpAndExit(prog);
    }

    // c.name === '--a'
    if (c.explicit !== null) {
      a = c.explicit;
      aSeen = true;
      i++;
      continue;
    }
    const next = argv[i + 1];
    if (next === undefined) {
      errorExit(prog, 'argument --a: expected one argument');
    }
    const nc = classified[i + 1];
    if (nc.kind !== 'value') {
      // option-like token or '--' cannot serve as --a's value
      errorExit(prog, 'argument --a: expected one argument');
    }
    a = next;
    aSeen = true;
    i += 2;
  }

  // parse_known_args checks required arguments before parse_args reports extras.
  if (!aSeen) {
    errorExit(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a };
}

