// resolver.mjs — PyYAML SafeLoader implicit resolver + SafeConstructor scalar
// constructors, reimplemented with manual character scanning (no RegExp, no JSON).
//
// Exports:
//   resolvePlainScalar(text)   — implicit typing of an untagged plain scalar
//   resolveTaggedScalar(tag, text) — construct a scalar with an explicit full tag
//   resolvesToString(text)     — true iff resolvePlainScalar(text) yields a string
//   isMergeKey(text)           — text === '<<'

import { YamlError, YamlDate, YamlDateTime, YamlBinary } from './types.mjs';

// ---------------------------------------------------------------------------
// character helpers
// ---------------------------------------------------------------------------

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function digitValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'F') return ch.charCodeAt(0) - 65;
  return -1;
}

function toLower(text) {
  let out = '';
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    out += c >= 65 && c <= 90 ? String.fromCharCode(c + 32) : ch;
  }
  return out;
}

function removeUnderscores(text) {
  let out = '';
  for (const ch of text) {
    if (ch !== '_') out += ch;
  }
  return out;
}

// ---------------------------------------------------------------------------
// null / bool / merge
// ---------------------------------------------------------------------------

const BOOL_VALUES = {
  yes: true, Yes: true, YES: true,
  no: false, No: false, NO: false,
  true: true, True: true, TRUE: true,
  false: false, False: false, FALSE: false,
  on: true, On: true, ON: true,
  off: false, Off: false, OFF: false,
};

function isNullWord(text) {
  return text === '' || text === '~' || text === 'null' || text === 'Null' || text === 'NULL';
}

// ---------------------------------------------------------------------------
// integers
// ---------------------------------------------------------------------------

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);
const MIN_SAFE = -MAX_SAFE;

function finishInt(v) {
  return v <= MAX_SAFE && v >= MIN_SAFE ? Number(v) : v;
}

// Parse a string of digits (already underscore-stripped) in the given base.
// Throws YamlError on empty input or a digit out of range — mirroring the
// ValueError raised by Python's int().
function parseBigIntBase(digits, base) {
  if (digits.length === 0) {
    throw new YamlError("invalid literal for int() with base " + base + ": ''");
  }
  const b = BigInt(base);
  let v = 0n;
  for (const ch of digits) {
    const d = digitValue(ch);
    if (d < 0 || d >= base) {
      throw new YamlError("invalid literal for int() with base " + base + ": '" + digits + "'");
    }
    v = v * b + BigInt(d);
  }
  return v;
}

function allOf(text, base) {
  // every char a valid digit for base, '_' allowed anywhere, at least one char
  if (text.length === 0) return false;
  for (const ch of text) {
    if (ch === '_') continue;
    const d = digitValue(ch);
    if (d < 0 || d >= base) return false;
  }
  return true;
}

// Sexagesimal group after a colon in implicit ints/floats: [0-5]?[0-9]
function isSexagesimalGroup(g) {
  if (g.length === 1) return isDigit(g[0]);
  if (g.length === 2) return g[0] >= '0' && g[0] <= '5' && isDigit(g[1]);
  return false;
}

function splitChar(text, sep) {
  const parts = [];
  let cur = '';
  for (const ch of text) {
    if (ch === sep) {
      parts.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  parts.push(cur);
  return parts;
}

// Implicit int matcher (PyYAML resolver regexp, anchored full match):
//   [-+]?0b[0-1_]+
//   [-+]?0[0-7_]+
//   [-+]?(?:0|[1-9][0-9_]*)
//   [-+]?0x[0-9a-fA-F_]+
//   [-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+
// Returns null when the text does not match.
function matchImplicitInt(text) {
  let rest = text;
  let neg = false;
  if (rest[0] === '+' || rest[0] === '-') {
    neg = rest[0] === '-';
    rest = rest.slice(1);
  }
  if (rest.length === 0) return null;
  let v;
  if (rest[0] === '0' && rest[1] === 'b') {
    const digits = rest.slice(2);
    if (!allOf(digits, 2)) return null;
    v = parseBigIntBase(removeUnderscores(digits), 2);
  } else if (rest[0] === '0' && rest[1] === 'x') {
    const digits = rest.slice(2);
    if (!allOf(digits, 16)) return null;
    v = parseBigIntBase(removeUnderscores(digits), 16);
  } else if (rest[0] === '0' && rest.length > 1 && allOf(rest.slice(1), 8)) {
    v = parseBigIntBase(removeUnderscores(rest), 8);
  } else if (rest === '0') {
    v = 0n;
  } else if (rest[0] >= '1' && rest[0] <= '9') {
    // decimal or sexagesimal
    if (rest.indexOf(':') < 0) {
      if (!allOf(rest, 10)) return null;
      v = parseBigIntBase(removeUnderscores(rest), 10);
    } else {
      const parts = splitChar(rest, ':');
      if (parts.length < 2) return null;
      const first = parts[0];
      if (!(first[0] >= '1' && first[0] <= '9') || !allOf(first, 10)) return null;
      for (let k = 1; k < parts.length; k++) {
        if (!isSexagesimalGroup(parts[k])) return null;
      }
      v = 0n;
      for (const part of parts) {
        v = v * 60n + parseBigIntBase(removeUnderscores(part), 10);
      }
    }
  } else {
    return null;
  }
  if (neg) v = -v;
  return finishInt(v);
}

// SafeConstructor.construct_yaml_int — accepts more than the implicit
// resolver (e.g. '0o17', '1:60', '_5'); invalid input throws YamlError.
function constructInt(text) {
  let v = removeUnderscores(text);
  let neg = false;
  if (v[0] === '-') {
    neg = true;
    v = v.slice(1);
  } else if (v[0] === '+') {
    v = v.slice(1);
  }
  if (v === '0') return 0;
  let result;
  if (v.startsWith('0b')) {
    result = parseBigIntBase(v.slice(2), 2);
  } else if (v.startsWith('0x')) {
    result = parseBigIntBase(v.slice(2), 16);
  } else if (v.startsWith('0o')) {
    result = parseBigIntBase(v.slice(2), 8);
  } else if (v[0] === '0') {
    result = parseBigIntBase(v, 8);
  } else if (v.indexOf(':') >= 0) {
    const parts = splitChar(v, ':');
    result = 0n;
    for (const part of parts) {
      result = result * 60n + parseBigIntBase(part, 10);
    }
  } else {
    result = parseBigIntBase(v, 10);
  }
  if (neg) result = -result;
  return finishInt(result);
}

// ---------------------------------------------------------------------------
// floats
// ---------------------------------------------------------------------------

// exponent part of an implicit float: [eE][-+][0-9]+  (sign REQUIRED)
function matchImplicitExponent(text, i) {
  if (i >= text.length) return true; // no exponent — ok
  if (text[i] !== 'e' && text[i] !== 'E') return false;
  i++;
  if (i >= text.length || (text[i] !== '+' && text[i] !== '-')) return false;
  i++;
  const start = i;
  while (i < text.length && isDigit(text[i])) i++;
  return i > start && i === text.length;
}

// Implicit float matcher (PyYAML resolver regexp, anchored full match):
//   [-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?
//   \.[0-9][0-9_]*(?:[eE][-+][0-9]+)?            (NO sign allowed)
//   [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//   [-+]?\.(?:inf|Inf|INF)
//   \.(?:nan|NaN|NAN)                            (NO sign allowed)
// Returns null when the text does not match.
function matchImplicitFloat(text) {
  // specials without sign
  if (text === '.nan' || text === '.NaN' || text === '.NAN') return NaN;
  let s = text;
  let neg = false;
  let hasSign = false;
  if (s[0] === '+' || s[0] === '-') {
    hasSign = true;
    neg = s[0] === '-';
    s = s.slice(1);
  }
  if (s === '.inf' || s === '.Inf' || s === '.INF') return neg ? -Infinity : Infinity;
  if (s.length === 0) return null;

  // sexagesimal float
  if (s.indexOf(':') >= 0) {
    const parts = splitChar(s, ':');
    if (parts.length < 2) return null;
    // last part: [0-5]?[0-9]\.[0-9_]*  (the dot is mandatory)
    const last = parts[parts.length - 1];
    const dot = last.indexOf('.');
    if (dot < 0) return null;
    const lastInt = last.slice(0, dot);
    const lastFrac = last.slice(dot + 1);
    if (!isSexagesimalGroup(lastInt)) return null;
    if (!fracOk(lastFrac)) return null;
    if (!plainDigitsOk(parts[0])) return null;
    for (let k = 1; k < parts.length - 1; k++) {
      if (!isSexagesimalGroup(parts[k])) return null;
    }
    let v = 0;
    for (const part of parts) {
      v = v * 60 + Number(removeUnderscores(part));
    }
    return neg ? -v : v;
  }

  // dotted forms
  const dot = s.indexOf('.');
  if (dot < 0) return null;
  const intPart = s.slice(0, dot);
  const rest = s.slice(dot + 1);
  // split rest into fraction digits/underscores and possible exponent
  let i = 0;
  while (i < rest.length && (isDigit(rest[i]) || rest[i] === '_')) i++;
  const fracPart = rest.slice(0, i);
  if (intPart.length === 0) {
    // branch 2: leading dot — no sign permitted, at least one frac digit
    if (hasSign) return null;
    if (fracPart.length === 0) return null;
  } else {
    if (!plainDigitsOk(intPart)) return null;
  }
  if (!matchImplicitExponent(rest, i)) return null;
  const n = Number((neg ? '-' : '') + removeUnderscores(s));
  return n;
}

// [0-9][0-9_]*  (at least one digit, digits/underscores after)
function plainDigitsOk(text) {
  if (text.length === 0 || !isDigit(text[0])) return false;
  for (let k = 1; k < text.length; k++) {
    const ch = text[k];
    if (!isDigit(ch) && ch !== '_') return false;
  }
  return true;
}

// [0-9_]*  (possibly empty)
function fracOk(text) {
  for (const ch of text) {
    if (!isDigit(ch) && ch !== '_') return false;
  }
  return true;
}

// Strict Python float() literal: [0-9]+(\.[0-9]*)? | \.[0-9]+  with optional
// exponent [eE][+-]?[0-9]+  (sign optional here, unlike the implicit resolver)
function isValidPyFloat(s) {
  let i = 0;
  let before = 0;
  while (i < s.length && isDigit(s[i])) { i++; before++; }
  let after = 0;
  if (s[i] === '.') {
    i++;
    while (i < s.length && isDigit(s[i])) { i++; after++; }
  }
  if (before === 0 && after === 0) return false;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] === '+' || s[i] === '-') i++;
    let e = 0;
    while (i < s.length && isDigit(s[i])) { i++; e++; }
    if (e === 0) return false;
  }
  return i === s.length;
}

// SafeConstructor.construct_yaml_float — invalid input throws YamlError.
function constructFloat(text) {
  let v = toLower(removeUnderscores(text));
  let neg = false;
  if (v[0] === '-') {
    neg = true;
    v = v.slice(1);
  } else if (v[0] === '+') {
    v = v.slice(1);
  }
  if (v === '.inf') return neg ? -Infinity : Infinity;
  if (v === '.nan') return NaN;
  if (v.indexOf(':') >= 0) {
    const parts = splitChar(v, ':');
    let r = 0;
    for (const part of parts) {
      if (!isValidPyFloat(part)) {
        throw new YamlError("could not convert string to float: '" + text + "'");
      }
      r = r * 60 + Number(part);
    }
    return neg ? -r : r;
  }
  // fall through to Python float(): accepts inf/infinity/nan too
  if (v === 'inf' || v === 'infinity') return neg ? -Infinity : Infinity;
  if (v === 'nan') return NaN;
  if (!isValidPyFloat(v)) {
    throw new YamlError("could not convert string to float: '" + text + "'");
  }
  return Number((neg ? '-' : '') + v);
}

// ---------------------------------------------------------------------------
// timestamps
// ---------------------------------------------------------------------------

// Read between min and max decimal digits starting at i.
// Returns {value, count, next} or null.
function readDigits(text, i, min, max) {
  let j = i;
  while (j < text.length && j - i < max && isDigit(text[j])) j++;
  if (j - i < min) return null;
  return { value: Number(text.slice(i, j)), count: j - i, next: j };
}

function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

// Shape match of PyYAML's timestamp regexp (constructor version, which allows
// 1-digit month/day/hour). Returns a fields object or null.
//   YYYY-M-D
//   YYYY-M-D (T|t|[ \t]+) H:MM:SS (\.digits)? ([ \t]*(Z|[-+]H(:MM)?))?
function parseTimestampShape(text) {
  let r = readDigits(text, 0, 4, 4);
  if (!r) return null;
  const year = r.value;
  let i = r.next;
  if (text[i] !== '-') return null;
  i++;
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const month = r.value;
  const monthLen = r.count;
  i = r.next;
  if (text[i] !== '-') return null;
  i++;
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const day = r.value;
  const dayLen = r.count;
  i = r.next;
  if (i === text.length) {
    return { dateOnly: true, year, month, day, monthLen, dayLen };
  }
  const sep = text[i];
  if (sep === 'T' || sep === 't') {
    i++;
  } else if (isSpaceOrTab(sep)) {
    while (i < text.length && isSpaceOrTab(text[i])) i++;
  } else {
    return null;
  }
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const hour = r.value;
  i = r.next;
  if (text[i] !== ':') return null;
  i++;
  r = readDigits(text, i, 2, 2);
  if (!r) return null;
  const minute = r.value;
  i = r.next;
  if (text[i] !== ':') return null;
  i++;
  r = readDigits(text, i, 2, 2);
  if (!r) return null;
  const second = r.value;
  i = r.next;
  let fraction = '';
  if (text[i] === '.') {
    i++;
    const start = i;
    while (i < text.length && isDigit(text[i])) i++;
    fraction = text.slice(start, i);
  }
  let tz = null;
  if (i < text.length) {
    if (isSpaceOrTab(text[i])) {
      // whitespace is only allowed as part of the timezone group
      while (i < text.length && isSpaceOrTab(text[i])) i++;
      if (i === text.length) return null;
    }
    const ch = text[i];
    if (ch === 'Z') {
      tz = 0;
      i++;
    } else if (ch === '+' || ch === '-') {
      const sign = ch === '-' ? -1 : 1;
      i++;
      r = readDigits(text, i, 1, 2);
      if (!r) return null;
      const tzHour = r.value;
      i = r.next;
      let tzMinute = 0;
      if (text[i] === ':') {
        i++;
        r = readDigits(text, i, 2, 2);
        if (!r) return null;
        tzMinute = r.value;
        i = r.next;
      }
      tz = sign * (tzHour * 60 + tzMinute);
    } else {
      return null;
    }
  }
  if (i !== text.length) return null;
  return { dateOnly: false, year, month, day, hour, minute, second, fraction, tz };
}

function daysInMonth(year, month) {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    return leap ? 29 : 28;
  }
  if (month === 4 || month === 6 || month === 9 || month === 11) return 30;
  return 31;
}

// Python datetime() validation, then build YamlDate / YamlDateTime.
function buildTimestamp(m) {
  if (m.year < 1 || m.year > 9999) {
    throw new YamlError('year ' + m.year + ' is out of range');
  }
  if (m.month < 1 || m.month > 12) {
    throw new YamlError('month must be in 1..12');
  }
  if (m.day < 1 || m.day > daysInMonth(m.year, m.month)) {
    throw new YamlError('day is out of range for month');
  }
  if (m.dateOnly) {
    return new YamlDate(m.year, m.month, m.day);
  }
  if (m.hour > 23) {
    throw new YamlError('hour must be in 0..23');
  }
  if (m.minute > 59) {
    throw new YamlError('minute must be in 0..59');
  }
  if (m.second > 59) {
    throw new YamlError('second must be in 0..59');
  }
  let micro = 0;
  if (m.fraction.length > 0) {
    let f = m.fraction;
    while (f.length < 6) f += '0';
    micro = Number(f.slice(0, 6));
  }
  if (m.tz !== null && (m.tz >= 1440 || m.tz <= -1440)) {
    throw new YamlError(
      'offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24)');
  }
  return new YamlDateTime(m.year, m.month, m.day, m.hour, m.minute, m.second, micro, m.tz);
}

// Implicit timestamp resolution: like the constructor, except the date-only
// form requires exactly 2-digit month and day (resolver regexp).
// Returns null when the shape does not match.
function matchImplicitTimestamp(text) {
  const m = parseTimestampShape(text);
  if (!m) return null;
  if (m.dateOnly && (m.monthLen !== 2 || m.dayLen !== 2)) return null;
  return buildTimestamp(m);
}

// ---------------------------------------------------------------------------
// binary (base64)
// ---------------------------------------------------------------------------

const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function decodeBase64(text) {
  let data = '';
  let pad = 0;
  for (const ch of text) {
    if (ch === '=') {
      pad++;
    } else if (B64_ALPHABET.indexOf(ch) >= 0) {
      if (pad > 0) {
        throw new YamlError('failed to decode base64 data: Incorrect padding');
      }
      data += ch;
    }
    // any other character (whitespace included) is skipped, like binascii
  }
  if (pad > 2 || (data.length + pad) % 4 !== 0) {
    throw new YamlError('failed to decode base64 data: Incorrect padding');
  }
  const bytes = [];
  for (let i = 0; i < data.length; i += 4) {
    const a = B64_ALPHABET.indexOf(data[i]);
    const b = i + 1 < data.length ? B64_ALPHABET.indexOf(data[i + 1]) : 0;
    const c = i + 2 < data.length ? B64_ALPHABET.indexOf(data[i + 2]) : 0;
    const d = i + 3 < data.length ? B64_ALPHABET.indexOf(data[i + 3]) : 0;
    const n = (a << 18) | (b << 12) | (c << 6) | d;
    bytes.push((n >> 16) & 255);
    if (i + 2 < data.length) bytes.push((n >> 8) & 255);
    if (i + 3 < data.length) bytes.push(n & 255);
  }
  return new YamlBinary(new Uint8Array(bytes));
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

const TAG_PREFIX = 'tag:yaml.org,2002:';

// Resolve a plain (untagged, unquoted) scalar to its JS value,
// PyYAML SafeLoader semantics.
export function resolvePlainScalar(text) {
  if (isNullWord(text)) return null;
  if (Object.prototype.hasOwnProperty.call(BOOL_VALUES, text)) return BOOL_VALUES[text];
  const asInt = matchImplicitInt(text);
  if (asInt !== null) return asInt;
  const asFloat = matchImplicitFloat(text);
  if (asFloat !== null) return asFloat;
  const asTs = matchImplicitTimestamp(text);
  if (asTs !== null) return asTs;
  if (text === '<<') {
    // resolves to tag:yaml.org,2002:merge, which SafeConstructor cannot
    // construct as a scalar — same failure as PyYAML's construct_undefined
    throw new YamlError(
      "could not determine a constructor for the tag 'tag:yaml.org,2002:merge'");
  }
  return text;
}

// Resolve a scalar that carries an explicit full tag.
// Throws YamlError for unknown tags or values the constructor rejects.
export function resolveTaggedScalar(tag, text) {
  let suffix;
  if (tag.startsWith(TAG_PREFIX)) {
    suffix = tag.slice(TAG_PREFIX.length);
  } else if (tag.startsWith('!!')) {
    suffix = tag.slice(2);
  } else {
    throw new YamlError("could not determine a constructor for the tag '" + tag + "'");
  }
  switch (suffix) {
    case 'str':
      return text;
    case 'null':
      // SafeConstructor.construct_yaml_null ignores the value entirely
      return null;
    case 'bool':
      if (Object.prototype.hasOwnProperty.call(BOOL_VALUES, text)) return BOOL_VALUES[text];
      throw new YamlError("could not determine a boolean value for '" + text + "'");
    case 'int':
      return constructInt(text);
    case 'float':
      return constructFloat(text);
    case 'binary':
      return decodeBase64(text);
    case 'timestamp': {
      const m = parseTimestampShape(text);
      if (!m) {
        throw new YamlError("could not interpret '" + text + "' as a timestamp");
      }
      return buildTimestamp(m);
    }
    default:
      throw new YamlError("could not determine a constructor for the tag '" + tag + "'");
  }
}

// True iff resolvePlainScalar(text) would return a string (emitter uses this
// to decide whether a plain-style scalar must be quoted).
export function resolvesToString(text) {
  try {
    return typeof resolvePlainScalar(text) === 'string';
  } catch {
    return false;
  }
}

// The merge-key marker check for mapping keys.
export function isMergeKey(text) {
  return text === '<<';
}

display.content:
// resolver.mjs — PyYAML SafeLoader implicit resolver + SafeConstructor scalar
// constructors, reimplemented with manual character scanning (no RegExp, no JSON).
//
// Exports:
//   resolvePlainScalar(text)   — implicit typing of an untagged plain scalar
//   resolveTaggedScalar(tag, text) — construct a scalar with an explicit full tag
//   resolvesToString(text)     — true iff resolvePlainScalar(text) yields a string
//   isMergeKey(text)           — text === '<<'

import { YamlError, YamlDate, YamlDateTime, YamlBinary } from './types.mjs';

// ---------------------------------------------------------------------------
// character helpers
// ---------------------------------------------------------------------------

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function digitValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'F') return ch.charCodeAt(0) - 65;
  return -1;
}

function toLower(text) {
  let out = '';
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    out += c >= 65 && c <= 90 ? String.fromCharCode(c + 32) : ch;
  }
  return out;
}

function removeUnderscores(text) {
  let out = '';
  for (const ch of text) {
    if (ch !== '_') out += ch;
  }
  return out;
}

// ---------------------------------------------------------------------------
// null / bool / merge
// ---------------------------------------------------------------------------

const BOOL_VALUES = {
  yes: true, Yes: true, YES: true,
  no: false, No: false, NO: false,
  true: true, True: true, TRUE: true,
  false: false, False: false, FALSE: false,
  on: true, On: true, ON: true,
  off: false, Off: false, OFF: false,
};

function isNullWord(text) {
  return text === '' || text === '~' || text === 'null' || text === 'Null' || text === 'NULL';
}

// ---------------------------------------------------------------------------
// integers
// ---------------------------------------------------------------------------

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);
const MIN_SAFE = -MAX_SAFE;

function finishInt(v) {
  return v <= MAX_SAFE && v >= MIN_SAFE ? Number(v) : v;
}

// Parse a string of digits (already underscore-stripped) in the given base.
// Throws YamlError on empty input or a digit out of range — mirroring the
// ValueError raised by Python's int().
function parseBigIntBase(digits, base) {
  if (digits.length === 0) {
    throw new YamlError("invalid literal for int() with base " + base + ": ''");
  }
  const b = BigInt(base);
  let v = 0n;
  for (const ch of digits) {
    const d = digitValue(ch);
    if (d < 0 || d >= base) {
      throw new YamlError("invalid literal for int() with base " + base + ": '" + digits + "'");
    }
    v = v * b + BigInt(d);
  }
  return v;
}

function allOf(text, base) {
  // every char a valid digit for base, '_' allowed anywhere, at least one char
  if (text.length === 0) return false;
  for (const ch of text) {
    if (ch === '_') continue;
    const d = digitValue(ch);
    if (d < 0 || d >= base) return false;
  }
  return true;
}

// Sexagesimal group after a colon in implicit ints/floats: [0-5]?[0-9]
function isSexagesimalGroup(g) {
  if (g.length === 1) return isDigit(g[0]);
  if (g.length === 2) return g[0] >= '0' && g[0] <= '5' && isDigit(g[1]);
  return false;
}

function splitChar(text, sep) {
  const parts = [];
  let cur = '';
  for (const ch of text) {
    if (ch === sep) {
      parts.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  parts.push(cur);
  return parts;
}

// Implicit int matcher (PyYAML resolver regexp, anchored full match):
//   [-+]?0b[0-1_]+
//   [-+]?0[0-7_]+
//   [-+]?(?:0|[1-9][0-9_]*)
//   [-+]?0x[0-9a-fA-F_]+
//   [-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+
// Returns null when the text does not match.
function matchImplicitInt(text) {
  let rest = text;
  let neg = false;
  if (rest[0] === '+' || rest[0] === '-') {
    neg = rest[0] === '-';
    rest = rest.slice(1);
  }
  if (rest.length === 0) return null;
  let v;
  if (rest[0] === '0' && rest[1] === 'b') {
    const digits = rest.slice(2);
    if (!allOf(digits, 2)) return null;
    v = parseBigIntBase(removeUnderscores(digits), 2);
  } else if (rest[0] === '0' && rest[1] === 'x') {
    const digits = rest.slice(2);
    if (!allOf(digits, 16)) return null;
    v = parseBigIntBase(removeUnderscores(digits), 16);
  } else if (rest[0] === '0' && rest.length > 1 && allOf(rest.slice(1), 8)) {
    v = parseBigIntBase(removeUnderscores(rest), 8);
  } else if (rest === '0') {
    v = 0n;
  } else if (rest[0] >= '1' && rest[0] <= '9') {
    // decimal or sexagesimal
    if (rest.indexOf(':') < 0) {
      if (!allOf(rest, 10)) return null;
      v = parseBigIntBase(removeUnderscores(rest), 10);
    } else {
      const parts = splitChar(rest, ':');
      if (parts.length < 2) return null;
      const first = parts[0];
      if (!(first[0] >= '1' && first[0] <= '9') || !allOf(first, 10)) return null;
      for (let k = 1; k < parts.length; k++) {
        if (!isSexagesimalGroup(parts[k])) return null;
      }
      v = 0n;
      for (const part of parts) {
        v = v * 60n + parseBigIntBase(removeUnderscores(part), 10);
      }
    }
  } else {
    return null;
  }
  if (neg) v = -v;
  return finishInt(v);
}

// SafeConstructor.construct_yaml_int — accepts more than the implicit
// resolver (e.g. '0o17', '1:60', '_5'); invalid input throws YamlError.
function constructInt(text) {
  let v = removeUnderscores(text);
  let neg = false;
  if (v[0] === '-') {
    neg = true;
    v = v.slice(1);
  } else if (v[0] === '+') {
    v = v.slice(1);
  }
  if (v === '0') return 0;
  let result;
  if (v.startsWith('0b')) {
    result = parseBigIntBase(v.slice(2), 2);
  } else if (v.startsWith('0x')) {
    result = parseBigIntBase(v.slice(2), 16);
  } else if (v.startsWith('0o')) {
    result = parseBigIntBase(v.slice(2), 8);
  } else if (v[0] === '0') {
    result = parseBigIntBase(v, 8);
  } else if (v.indexOf(':') >= 0) {
    const parts = splitChar(v, ':');
    result = 0n;
    for (const part of parts) {
      result = result * 60n + parseBigIntBase(part, 10);
    }
  } else {
    result = parseBigIntBase(v, 10);
  }
  if (neg) result = -result;
  return finishInt(result);
}

// ---------------------------------------------------------------------------
// floats
// ---------------------------------------------------------------------------

// exponent part of an implicit float: [eE][-+][0-9]+  (sign REQUIRED)
function matchImplicitExponent(text, i) {
  if (i >= text.length) return true; // no exponent — ok
  if (text[i] !== 'e' && text[i] !== 'E') return false;
  i++;
  if (i >= text.length || (text[i] !== '+' && text[i] !== '-')) return false;
  i++;
  const start = i;
  while (i < text.length && isDigit(text[i])) i++;
  return i > start && i === text.length;
}

// Implicit float matcher (PyYAML resolver regexp, anchored full match):
//   [-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?
//   \.[0-9][0-9_]*(?:[eE][-+][0-9]+)?            (NO sign allowed)
//   [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//   [-+]?\.(?:inf|Inf|INF)
//   \.(?:nan|NaN|NAN)                            (NO sign allowed)
// Returns null when the text does not match.
function matchImplicitFloat(text) {
  // specials without sign
  if (text === '.nan' || text === '.NaN' || text === '.NAN') return NaN;
  let s = text;
  let neg = false;
  let hasSign = false;
  if (s[0] === '+' || s[0] === '-') {
    hasSign = true;
    neg = s[0] === '-';
    s = s.slice(1);
  }
  if (s === '.inf' || s === '.Inf' || s === '.INF') return neg ? -Infinity : Infinity;
  if (s.length === 0) return null;

  // sexagesimal float
  if (s.indexOf(':') >= 0) {
    const parts = splitChar(s, ':');
    if (parts.length < 2) return null;
    // last part: [0-5]?[0-9]\.[0-9_]*  (the dot is mandatory)
    const last = parts[parts.length - 1];
    const dot = last.indexOf('.');
    if (dot < 0) return null;
    const lastInt = last.slice(0, dot);
    const lastFrac = last.slice(dot + 1);
    if (!isSexagesimalGroup(lastInt)) return null;
    if (!fracOk(lastFrac)) return null;
    if (!plainDigitsOk(parts[0])) return null;
    for (let k = 1; k < parts.length - 1; k++) {
      if (!isSexagesimalGroup(parts[k])) return null;
    }
    let v = 0;
    for (const part of parts) {
      v = v * 60 + Number(removeUnderscores(part));
    }
    return neg ? -v : v;
  }

  // dotted forms
  const dot = s.indexOf('.');
  if (dot < 0) return null;
  const intPart = s.slice(0, dot);
  const rest = s.slice(dot + 1);
  // split rest into fraction digits/underscores and possible exponent
  let i = 0;
  while (i < rest.length && (isDigit(rest[i]) || rest[i] === '_')) i++;
  const fracPart = rest.slice(0, i);
  if (intPart.length === 0) {
    // branch 2: leading dot — no sign permitted, at least one frac digit
    if (hasSign) return null;
    if (fracPart.length === 0) return null;
  } else {
    if (!plainDigitsOk(intPart)) return null;
  }
  if (!matchImplicitExponent(rest, i)) return null;
  const n = Number((neg ? '-' : '') + removeUnderscores(s));
  return n;
}

// [0-9][0-9_]*  (at least one digit, digits/underscores after)
function plainDigitsOk(text) {
  if (text.length === 0 || !isDigit(text[0])) return false;
  for (let k = 1; k < text.length; k++) {
    const ch = text[k];
    if (!isDigit(ch) && ch !== '_') return false;
  }
  return true;
}

// [0-9_]*  (possibly empty)
function fracOk(text) {
  for (const ch of text) {
    if (!isDigit(ch) && ch !== '_') return false;
  }
  return true;
}

// Strict Python float() literal: [0-9]+(\.[0-9]*)? | \.[0-9]+  with optional
// exponent [eE][+-]?[0-9]+  (sign optional here, unlike the implicit resolver)
function isValidPyFloat(s) {
  let i = 0;
  let before = 0;
  while (i < s.length && isDigit(s[i])) { i++; before++; }
  let after = 0;
  if (s[i] === '.') {
    i++;
    while (i < s.length && isDigit(s[i])) { i++; after++; }
  }
  if (before === 0 && after === 0) return false;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] === '+' || s[i] === '-') i++;
    let e = 0;
    while (i < s.length && isDigit(s[i])) { i++; e++; }
    if (e === 0) return false;
  }
  return i === s.length;
}

// SafeConstructor.construct_yaml_float — invalid input throws YamlError.
function constructFloat(text) {
  let v = toLower(removeUnderscores(text));
  let neg = false;
  if (v[0] === '-') {
    neg = true;
    v = v.slice(1);
  } else if (v[0] === '+') {
    v = v.slice(1);
  }
  if (v === '.inf') return neg ? -Infinity : Infinity;
  if (v === '.nan') return NaN;
  if (v.indexOf(':') >= 0) {
    const parts = splitChar(v, ':');
    let r = 0;
    for (const part of parts) {
      if (!isValidPyFloat(part)) {
        throw new YamlError("could not convert string to float: '" + text + "'");
      }
      r = r * 60 + Number(part);
    }
    return neg ? -r : r;
  }
  // fall through to Python float(): accepts inf/infinity/nan too
  if (v === 'inf' || v === 'infinity') return neg ? -Infinity : Infinity;
  if (v === 'nan') return NaN;
  if (!isValidPyFloat(v)) {
    throw new YamlError("could not convert string to float: '" + text + "'");
  }
  return Number((neg ? '-' : '') + v);
}

// ---------------------------------------------------------------------------
// timestamps
// ---------------------------------------------------------------------------

// Read between min and max decimal digits starting at i.
// Returns {value, count, next} or null.
function readDigits(text, i, min, max) {
  let j = i;
  while (j < text.length && j - i < max && isDigit(text[j])) j++;
  if (j - i < min) return null;
  return { value: Number(text.slice(i, j)), count: j - i, next: j };
}

function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

// Shape match of PyYAML's timestamp regexp (constructor version, which allows
// 1-digit month/day/hour). Returns a fields object or null.
//   YYYY-M-D
//   YYYY-M-D (T|t|[ \t]+) H:MM:SS (\.digits)? ([ \t]*(Z|[-+]H(:MM)?))?
function parseTimestampShape(text) {
  let r = readDigits(text, 0, 4, 4);
  if (!r) return null;
  const year = r.value;
  let i = r.next;
  if (text[i] !== '-') return null;
  i++;
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const month = r.value;
  const monthLen = r.count;
  i = r.next;
  if (text[i] !== '-') return null;
  i++;
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const day = r.value;
  const dayLen = r.count;
  i = r.next;
  if (i === text.length) {
    return { dateOnly: true, year, month, day, monthLen, dayLen };
  }
  const sep = text[i];
  if (sep === 'T' || sep === 't') {
    i++;
  } else if (isSpaceOrTab(sep)) {
    while (i < text.length && isSpaceOrTab(text[i])) i++;
  } else {
    return null;
  }
  r = readDigits(text, i, 1, 2);
  if (!r) return null;
  const hour = r.value;
  i = r.next;
  if (text[i] !== ':') return null;
  i++;
  r = readDigits(text, i, 2, 2);
  if (!r) return null;
  const minute = r.value;
  i = r.next;
  if (text[i] !== ':') return null;
  i++;
  r = readDigits(text, i, 2, 2);
  if (!r) return null;
  const second = r.value;
  i = r.next;
  let fraction = '';
  if (text[i] === '.') {
    i++;
    const start = i;
    while (i < text.length && isDigit(text[i])) i++;
    fraction = text.slice(start, i);
  }
  let tz = null;
  if (i < text.length) {
    if (isSpaceOrTab(text[i])) {
      // whitespace is only allowed as part of the timezone group
      while (i < text.length && isSpaceOrTab(text[i])) i++;
      if (i === text.length) return null;
    }
    const ch = text[i];
    if (ch === 'Z') {
      tz = 0;
      i++;
    } else if (ch === '+' || ch === '-') {
      const sign = ch === '-' ? -1 : 1;
      i++;
      r = readDigits(text, i, 1, 2);
      if (!r) return null;
      const tzHour = r.value;
      i = r.next;
      let tzMinute = 0;
      if (text[i] === ':') {
        i++;
        r = readDigits(text, i, 2, 2);
        if (!r) return null;
        tzMinute = r.value;
        i = r.next;
      }
      tz = sign * (tzHour * 60 + tzMinute);
    } else {
      return null;
    }
  }
  if (i !== text.length) return null;
  return { dateOnly: false, year, month, day, hour, minute, second, fraction, tz };
}

function daysInMonth(year, month) {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    return leap ? 29 : 28;
  }
  if (month === 4 || month === 6 || month === 9 || month === 11) return 30;
  return 31;
}

// Python datetime() validation, then build YamlDate / YamlDateTime.
function buildTimestamp(m) {
  if (m.year < 1 || m.year > 9999) {
    throw new YamlError('year ' + m.year + ' is out of range');
  }
  if (m.month < 1 || m.month > 12) {
    throw new YamlError('month must be in 1..12');
  }
  if (m.day < 1 || m.day > daysInMonth(m.year, m.month)) {
    throw new YamlError('day is out of range for month');
  }
  if (m.dateOnly) {
    return new YamlDate(m.year, m.month, m.day);
  }
  if (m.hour > 23) {
    throw new YamlError('hour must be in 0..23');
  }
  if (m.minute > 59) {
    throw new YamlError('minute must be in 0..59');
  }
  if (m.second > 59) {
    throw new YamlError('second must be in 0..59');
  }
  let micro = 0;
  if (m.fraction.length > 0) {
    let f = m.fraction;
    while (f.length < 6) f += '0';
    micro = Number(f.slice(0, 6));
  }
  if (m.tz !== null && (m.tz >= 1440 || m.tz <= -1440)) {
    throw new YamlError(
      'offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24)');
  }
  return new YamlDateTime(m.year, m.month, m.day, m.hour, m.minute, m.second, micro, m.tz);
}

// Implicit timestamp resolution: like the constructor, except the date-only
// form requires exactly 2-digit month and day (resolver regexp).
// Returns null when the shape does not match.
function matchImplicitTimestamp(text) {
  const m = parseTimestampShape(text);
  if (!m) return null;
  if (m.dateOnly && (m.monthLen !== 2 || m.dayLen !== 2)) return null;
  return buildTimestamp(m);
}

// ---------------------------------------------------------------------------
// binary (base64)
// ---------------------------------------------------------------------------

const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function decodeBase64(text) {
  let data = '';
  let pad = 0;
  for (const ch of text) {
    if (ch === '=') {
      pad++;
    } else if (B64_ALPHABET.indexOf(ch) >= 0) {
      if (pad > 0) {
        throw new YamlError('failed to decode base64 data: Incorrect padding');
      }
      data += ch;
    }
    // any other character (whitespace included) is skipped, like binascii
  }
  if (pad > 2 || (data.length + pad) % 4 !== 0) {
    throw new YamlError('failed to decode base64 data: Incorrect padding');
  }
  const bytes = [];
  for (let i = 0; i < data.length; i += 4) {
    const a = B64_ALPHABET.indexOf(data[i]);
    const b = i + 1 < data.length ? B64_ALPHABET.indexOf(data[i + 1]) : 0;
    const c = i + 2 < data.length ? B64_ALPHABET.indexOf(data[i + 2]) : 0;
    const d = i + 3 < data.length ? B64_ALPHABET.indexOf(data[i + 3]) : 0;
    const n = (a << 18) | (b << 12) | (c << 6) | d;
    bytes.push((n >> 16) & 255);
    if (i + 2 < data.length) bytes.push((n >> 8) & 255);
    if (i + 3 < data.length) bytes.push(n & 255);
  }
  return new YamlBinary(new Uint8Array(bytes));
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

const TAG_PREFIX = 'tag:yaml.org,2002:';

// Resolve a plain (untagged, unquoted) scalar to its JS value,
// PyYAML SafeLoader semantics.
export function resolvePlainScalar(text) {
  if (isNullWord(text)) return null;
  if (Object.prototype.hasOwnProperty.call(BOOL_VALUES, text)) return BOOL_VALUES[text];
  const asInt = matchImplicitInt(text);
  if (asInt !== null) return asInt;
  const asFloat = matchImplicitFloat(text);
  if (asFloat !== null) return asFloat;
  const asTs = matchImplicitTimestamp(text);
  if (asTs !== null) return asTs;
  if (text === '<<') {
    // resolves to tag:yaml.org,2002:merge, which SafeConstructor cannot
    // construct as a scalar — same failure as PyYAML's construct_undefined
    throw new YamlError(
      "could not determine a constructor for the tag 'tag:yaml.org,2002:merge'");
  }
  return text;
}

// Resolve a scalar that carries an explicit full tag.
// Throws YamlError for unknown tags or values the constructor rejects.
export function resolveTaggedScalar(tag, text) {
  let suffix;
  if (tag.startsWith(TAG_PREFIX)) {
    suffix = tag.slice(TAG_PREFIX.length);
  } else if (tag.startsWith('!!')) {
    suffix = tag.slice(2);
  } else {
    throw new YamlError("could not determine a constructor for the tag '" + tag + "'");
  }
  switch (suffix) {
    case 'str':
      return text;
    case 'null':
      // SafeConstructor.construct_yaml_null ignores the value entirely
      return null;
    case 'bool':
      if (Object.prototype.hasOwnProperty.call(BOOL_VALUES, text)) return BOOL_VALUES[text];
      throw new YamlError("could not determine a boolean value for '" + text + "'");
    case 'int':
      return constructInt(text);
    case 'float':
      return constructFloat(text);
    case 'binary':
      return decodeBase64(text);
    case 'timestamp': {
      const m = parseTimestampShape(text);
      if (!m) {
        throw new YamlError("could not interpret '" + text + "' as a timestamp");
      }
      return buildTimestamp(m);
    }
    default:
      throw new YamlError("could not determine a constructor for the tag '" + tag + "'");
  }
}

// True iff resolvePlainScalar(text) would return a string (emitter uses this
// to decide whether a plain-style scalar must be quoted).
export function resolvesToString(text) {
  try {
    return typeof resolvePlainScalar(text) === 'string';
  } catch {
    return false;
  }
}

// The merge-key marker check for mapping keys.
export function isMergeKey(text) {
  return text === '<<';
}

