// integral numbers: digits must match; int/float distinction checked separately
const norm = (s) => {
  if (s.endsWith('|int?')) return s.slice(0, -5);
  if (s.endsWith('.0')) {
    const head = s.slice(0, -2);
    const digits = head[0] === '-' ? head.slice(1) : head;
    let allDigits = digits.length > 0;
    for (const ch of digits) if (ch < '0' || ch > '9') allDigits = false;
    if (allDigits) return head;
  }
  return s;
};

for (const [input, want] of plainCases) {
  let got;
  try {
    got = fmt(resolvePlainScalar(input));
  } catch (e) {
    got = 'ERROR';
  }
  const ok = norm(got) === norm(want) || got === want;

